uniform float lod: hint_range(0.0, 5) = 0.0;
uniform sampler2D SCREEN_TEXTURE : hint_screen_texture, filter_linear_mipmap;
uniform float brightness = 2.3;
uniform float noise_intensity = 0.5;
uniform vec2 camera_pos;
uniform mat2 camera_xform;
uniform sampler2D vignette;
uniform float vignette_intensity = 0.5;

float blendOverlay(float base, float blend) {
	return base<0.5?(2.0*base*blend):(1.0-2.0*(1.0-base)*(1.0-blend));
}

vec3 blendOverlay(vec3 base, vec3 blend) {
	return vec3(blendOverlay(base.r,blend.r),blendOverlay(base.g,blend.g),blendOverlay(base.b,blend.b));
}

vec3 blendOverlay(vec3 base, vec3 blend, float opacity) {
	return (blendOverlay(base, blend) * opacity + base * (1.0 - opacity));
}

void fragment() {
	float blur_intensity = max(0,length(vec2(0.5) - SCREEN_UV)-0.3);
	COLOR = texture(SCREEN_TEXTURE, SCREEN_UV, lod*blur_intensity);
	COLOR.rgb = mix(COLOR.rgb, blendOverlay(
		COLOR.rgb,
		texture(TEXTURE, (camera_xform*(UV/SCREEN_PIXEL_SIZE+camera_pos)*SCREEN_PIXEL_SIZE)).rgb*brightness, 1.0), noise_intensity - blur_intensity);
