render_mode unshaded, blend_mul;

uniform sampler2D SCREEN_TEXTURE : hint_screen_texture;
uniform float offset_strength = 1.0;
uniform float color_strength = 1.0;
// Overall blend amount. 0 leaves the screen untouched (multiply by white under
// blend_mul); 1 is the full acid distortion. Tween this to fade in/out.
