void fragment() {
    vec2 uv = UV;
    float timeRatio = .3;
    float timeFlow = TIME * timeRatio;
    float acidRatio = 5.;

    vec3 position = vec3(timeFlow, timeFlow, timeFlow);
    vec3 color = texture(SCREEN_TEXTURE, UV).rgb; //vec3(acidRatio, acidRatio, acidRatio);
    vec3 offset = vec3(-sin(uv), (sin(uv) - cos(uv)).x) * offset_strength;

    for (int i = 0; i < 20; i++) {
        position += offset;
    	color += vec3(
            -sin(color.g + sin(position.y)), 
            -sin(color.b + sin(position.z)), 
            -sin(color.r + sin(position.x)) 
        ) * color_strength;
    }

    color *= color * .03;

    COLOR.rgb = mix(COLOR.rgb, color, COLOR.a * strength);
}

