// Additive so the glow adds light on top of the already-bloomed floor glow it
// sits over, rather than alpha-mixing into it (where it washes out invisibly).
render_mode blend_add;

// Glow layer for the secret-path direction arrow. Sweeps the same vertical
// brightness band as the room floor's pulsing_glow.gdshader, but keyed off
// WORLD position instead of the sprite's own UV. That keeps the wave in sync
// with the floor in both rhythm AND position: because the arrow is small and
// sits at a fixed spot in the room, the room-spanning band only crosses it
// briefly, so a big wave washes over the arrow at long intervals.
//
// band_speed / band_width MUST match the floor glow material
// (SecretPathRoomGroundGlow) for the sync to hold. room_center_y / room_height
// describe the floor glow sprite's world-space vertical span: the band there is
// brightest where (1 - UV.y) == band_pos, i.e. at world Y =
// room_center_y + room_height * (0.5 - band_pos).

varying float world_y;

uniform float band_speed : hint_range(0.0, 2.0) = 0.15;
uniform float band_width : hint_range(0.01, 0.5) = 0.4;

// Vertical span of the floor glow sprite in GLOBAL (canvas world) space, to
// match the world_y computed from MODEL_MATRIX above. The level generator places
// rooms at arbitrary world positions, so rna_key_pickup.gd sets these per
// instance from the actual SecretPathRoomGroundGlow transform; the defaults only
// hold when the room sits at the world origin.
uniform float room_center_y = 0.0;
uniform float room_height = 7036.0;

// Extra brightness multiplier at the band peak, on top of the texture's own
// glow. 0 = the glow texture only fades in/out; >0 = it also brightens.
uniform float glow_boost : hint_range(0.0, 8.0) = 4.0;

void vertex() {
	// World position of this vertex (canvas space). y component is what the
	// floor band is computed against.
	world_y = (MODEL_MATRIX * vec4(VERTEX, 0.0, 1.0)).y;
}

void fragment() {
	COLOR = texture(TEXTURE, UV) * COLOR;

	// Reproduce the floor band's vertical sweep, then evaluate it at this
	// pixel's world Y rather than at the local UV. Floor: band brightest where
	// (1 - UV.y_floor) == band_pos, with UV.y_floor=0 at the floor sprite's top
	// (world Y = room_center_y - room_height/2). So:
	//   1 - UV.y_floor = (room_center_y + room_height/2 - world_y) / room_height
	float band_pos = fract(TIME * band_speed) * (1.0 + 2.0 * band_width) - band_width;
	float floor_coord = (room_center_y + room_height * 0.5 - world_y) / room_height;
	float dist = abs(floor_coord - band_pos);
	float band = smoothstep(band_width, 0.0, dist);

	COLOR.a *= band;
	COLOR.rgb *= 1.0 + glow_boost * band;
}

