void vertex() {
	local_y = VERTEX.y;
}

void fragment() {
	vec4 main_texture = textureLod(screen_texture, SCREEN_UV, 0.0);
	if (main_texture.a < 0.0001) {
		discard;
	}
	main_texture.rgb /= main_texture.a;
	COLOR *= main_texture;
	COLOR.a *= 1.0 - smoothstep(fade_start_y, fade_end_y, local_y);
}

